def clean(df):
    df = df.copy()
    df['Price'] = pd.to_numeric(
        df['Price'].astype(str).str.replace('$', '', regex=False).str.strip(),
        errors='coerce'
    )
    return df

def answer(df):
    df = clean(df)
    g = df.dropna(subset=['Category', 'Price']).groupby('Category')['Price'].mean()
    return {str(k): float(v) for k, v in g.items()}
